WITH parsed AS (SELECT id, customer_id, created_at, ship_to, attributes, EXISTS(coupon_codes, c -> c LIKE 'W%') AS has_welcome_code, TRANSFORM(items, li -> li.product_id) AS product_ids, COALESCE(attributes['device'], 'none') AS device_or_default FROM carts WHERE created_at < '2024-07-01') SELECT id, customer_id, device_or_default, LAST_VALUE(device_or_default) IGNORE NULLS OVER (PARTITION BY customer_id ORDER BY created_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_device_or_default FROM parsed
